<?php $root=dirname(__DIR__,3);$f=$root.'/logs/app.log';$n=isset($_GET['n'])?max(10,min(2000,(int)$_GET['n'])):200;$lines=[];if(is_file($f)){$s=filesize($f);$buf=$s<=1048576?file_get_contents($f):(fseek($h=fopen($f,'r'),$s-1048576)===0?stream_get_contents($h):'');$all=explode("\n",$buf);$lines=array_slice(array_filter($all),-$n);} echo json_encode(['ok'=>true,'lines'=>$lines]);